CREATE TABLE produits(id INTEGER PRIMARY KEY,nom TEXT NOT NULL,categorie TEXT NOT NULL,cout REAL NOT NULL,prix REAL NOT NULL,seuil INTEGER NOT NULL);
CREATE TABLE magasins(id INTEGER PRIMARY KEY,nom TEXT NOT NULL);
CREATE TABLE mouvements(id INTEGER PRIMARY KEY,produit_id INTEGER NOT NULL,magasin_id INTEGER NOT NULL,date_operation TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ("ENTREE","SORTIE")),quantite INTEGER NOT NULL CHECK(quantite>0),FOREIGN KEY(produit_id) REFERENCES produits(id),FOREIGN KEY(magasin_id) REFERENCES magasins(id));
CREATE TABLE ventes(id INTEGER PRIMARY KEY,mouvement_id INTEGER UNIQUE NOT NULL,remise REAL NOT NULL CHECK(remise BETWEEN 0 AND 1),FOREIGN KEY(mouvement_id) REFERENCES mouvements(id));